INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass staatliche Eingriffe immer die Wirtschaft ankurbeln. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wirkung hängt von Maßnahme ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich als IT-Firma von staatlichen Maßnahmen profitiere?', 3, '[{"text": "Investitionsförderung", "correct": true, "because": "Fördert Wachstum"}, {"text": "Schnellere Hardware", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen stabilisieren die Wirtschaft in einer Rezession?', 5, '[{"text": "Steuersenkungen", "correct": true, "because": "Erhöht Nachfrage"}, {"text": "Staatsausgaben erhöhen", "correct": true, "because": "Belebt Produktion"}, {"text": "Steuererhöhungen", "correct": false, "because": "Bremst Nachfrage"}, {"text": "Weniger Investitionen", "correct": false, "because": "Schwächt Wirtschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konjunkturpolitik wirkt antizyklisch. b) Sie fördert immer Inflation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Inflation nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich staatliche Förderung für IT-Projekte nutze?', 4, '[{"text": "Förderbedingungen", "correct": false, "because": "Müssen erfüllt werden"}, {"text": "Wirtschaftslage", "correct": false, "because": "Beeinflusst Maßnahmen"}, {"text": "Firmenlogo", "correct": true, "because": "Kein wirtschaftlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Konjunkturpolitik immer fiskalisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch geldpolitisch möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur Fiskalpolitik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit staatlichen IT-Investitionen in einer Krise?', 3, '[{"text": "Beschäftigung fördern", "correct": true, "because": "Schafft Arbeitsplätze"}, {"text": "Weniger Steuern", "correct": false, "because": "Nicht primär"}, {"text": "Schnellere CPUs", "correct": false, "because": "Kein direktes Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Instrumente nutzt der Staat zur Wirtschaftsförderung?', 5, '[{"text": "Staatsausgaben", "correct": true, "because": "Belebt Nachfrage"}, {"text": "Zinssenkungen", "correct": true, "because": "Fördert Investitionen"}, {"text": "Steuererhöhungen", "correct": false, "because": "Bremst Wirtschaft"}, {"text": "Weniger Regeln", "correct": false, "because": "Kein direktes Instrument"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Konjunkturpolitik hilft in Rezessionen. b) Sie ist immer langfristig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft kurzfristig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um von staatlicher Konjunkturpolitik zu profitieren?', 4, '[{"text": "Projektplan", "correct": false, "because": "Fördert Umsetzung"}, {"text": "Wirtschaftsdaten", "correct": false, "because": "Zeigt Bedarf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Konjunkturpolitik immer keynesianisch?', 2, '[{"text": "Nein", "correct": true, "because": "Auch monetaristisch möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur Keynes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine Zinssenkung für IT-Firmen?', 4, '[{"text": "Günstigere Kredite", "correct": true, "because": "Fördert Investitionen"}, {"text": "Höhere Nachfrage", "correct": true, "because": "Belebt Markt"}, {"text": "Schnellere Server", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Konjunkturpolitik Arbeitslosigkeit immer löst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wirkung begrenzt"}, {"text": "Ja", "correct": false, "because": "Nicht immer erfolgreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um als IT-Firma von staatlicher Nachfrageförderung zu profitieren?', 3, '[{"text": "Öffentliche Ausschreibungen", "correct": true, "because": "Bietet Aufträge"}, {"text": "Teure Hardware", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Staatsausgaben fördern die Wirtschaft. b) Sie erhöhen immer die Schulden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulden nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei staatlicher IT-Förderung?', 5, '[{"text": "Förderkriterien", "correct": true, "because": "Definiert Zugang"}, {"text": "Wirtschaftslage", "correct": true, "because": "Beeinflusst Maßnahmen"}, {"text": "Firmenfarben", "correct": false, "because": "Irrelevant"}, {"text": "Schnellere Netzwerke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Konjunkturmaßnahmen für IT nutze?', 3, '[{"text": "Antragsfristen", "correct": false, "because": "Bestimmen Zugang"}, {"text": "Förderbedingungen", "correct": false, "because": "Müssen erfüllt werden"}, {"text": "Bürodeko", "correct": true, "because": "Kein wirtschaftlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Stabilisiert Konjunkturpolitik immer die IT-Branche?', 3, '[{"text": "Nein", "correct": true, "because": "Effekt variiert"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Konjunkturpolitik nur in Krisen wirkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch präventiv möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur reaktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Instrument ist entscheidend, wenn der Staat die IT ankurbelt?', 4, '[{"text": "Subventionen", "correct": true, "because": "Fördert Projekte"}, {"text": "Weniger Regeln", "correct": false, "because": "Nicht direkt"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]');
